import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 12;
    static final int INF = 1000000;
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};
    static int N, T;
    static char[][] grid1 = new char[MAXN][MAXN];
    static char[][] grid2 = new char[MAXN][MAXN];
    static int[][] A = new int[MAXN][MAXN];
    static int[][][][] B = new int[MAXN][MAXN][MAXN][MAXN];

    static class Edge {
        int a, b, cap, flow;
        public Edge(int a, int b, int cap, int flow) {
            this.a = a;
            this.b = b;
            this.cap = cap;
            this.flow = flow;
        }
    }

    static int nodeCount, source, sink;
    static int[] dist, ptr, q;
    static ArrayList<Edge> edges;
    static ArrayList<Integer>[] g;

    static final int MAX_NETWORK_NODES = 2 * MAXN * MAXN + 2;

    static void addEdge(int a, int b, int cap) {
        Edge e1 = new Edge(a, b, cap, 0);
        Edge e2 = new Edge(b, a, 0, 0);
        g[a].add(edges.size()); edges.add(e1);
        g[b].add(edges.size()); edges.add(e2);
    }

    static boolean bfs() {
        int front = 0, back = 0;
        q[back++] = source;
        Arrays.fill(dist, -1);
        dist[source] = 0;
        while (front < back && dist[sink] == -1) {
            int v = q[front++];
            for (int id : g[v]) {
                int to = edges.get(id).b;
                if (dist[to] == -1 && edges.get(id).flow < edges.get(id).cap) {
                    q[back++] = to;
                    dist[to] = dist[v] + 1;
                }
            }
        }
        return dist[sink] != -1;
    }

    static int sendFlow(int v, int flow) {
        if (v == sink) return flow;
        for (; ptr[v] < g[v].size(); ptr[v]++) {
            int id = g[v].get(ptr[v]);
            int to = edges.get(id).b;
            if (dist[to] == dist[v] + 1 && edges.get(id).flow < edges.get(id).cap) {
                int pushed = Math.min(flow, edges.get(id).cap - edges.get(id).flow);
                int pushedFlow = sendFlow(to, pushed);
                if (pushedFlow > 0) {
                    edges.get(id).flow += pushedFlow;
                    edges.get(id ^ 1).flow -= pushedFlow;
                    return pushedFlow;
                }
            }
        }
        return 0;
    }

    static int maxFlow() {
        int total = 0;
        while (bfs()) {
            Arrays.fill(ptr, 0);
            int pushed;
            while ((pushed = sendFlow(source, INF)) > 0) {
                total += pushed;
            }
        }
        return total;
    }

    static int getID(int x, int y) {
        return x * N + y;
    }

    static void buildNetwork() {
        source = 0;
        sink = 2 * N * N + 1;
        nodeCount = 2 * N * N + 2;
        g = new ArrayList[nodeCount];
        for (int i = 0; i < nodeCount; i++) g[i] = new ArrayList<>();
        edges = new ArrayList<>();
        dist = new int[nodeCount];
        ptr = new int[nodeCount];
        q = new int[nodeCount];

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (grid1[i][j] > '0' && grid1[i][j] <= '9') {
                    addEdge(source, 1 + getID(i, j), grid1[i][j] - '0');
                }
                if (grid2[i][j] > '0' && grid2[i][j] <= '9') {
                    addEdge(N * N + 1 + getID(i, j), sink, grid2[i][j] - '0');
                }
            }
        }
        for (int x1 = 0; x1 < N; x1++) {
            for (int y1 = 0; y1 < N; y1++) {
                for (int x2 = 0; x2 < N; x2++) {
                    for (int y2 = 0; y2 < N; y2++) {
                        if (B[x1][y1][x2][y2] != 0) {
                            addEdge(1 + getID(x1, y1), N * N + 1 + getID(x2, y2), INF);
                        }
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Integer.parseInt(st.nextToken());
        T = Integer.parseInt(st.nextToken());
        for (int i = 0; i < N; i++) {
            grid1[i] = br.readLine().toCharArray();
        }
        for (int i = 0; i < N; i++) {
            grid2[i] = br.readLine().toCharArray();
        }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                A[i][j] = INF;
            }
        }
        Queue<int[]> Q = new LinkedList<>();
        for (int x = 0; x < N; x++) {
            for (int y = 0; y < N; y++) {
                if (grid1[x][y] == 'Z') {
                    for (int i = 0; i < 4; i++) {
                        int nx = x + dx[i], ny = y + dy[i];
                        if (nx >= 0 && nx < N && ny >= 0 && ny < N && grid1[nx][ny] != 'Y') {
                            A[nx][ny] = 1;
                            Q.offer(new int[]{nx, ny});
                        }
                    }
                }
            }
        }
        while (!Q.isEmpty()) {
            int[] p = Q.poll();
            int x = p[0], y = p[1];
            for (int i = 0; i < 4; i++) {
                int nx = x + dx[i], ny = y + dy[i];
                if (nx >= 0 && nx < N && ny >= 0 && ny < N && grid1[nx][ny] != 'Y' && grid1[nx][ny] != 'Z' && A[nx][ny] == INF) {
                    A[nx][ny] = A[x][y] + 1;
                    Q.offer(new int[]{nx, ny});
                }
            }
        }
        for (int x1 = 0; x1 < N; x1++) {
            for (int y1 = 0; y1 < N; y1++) {
                for (int x2 = 0; x2 < N; x2++) {
                    for (int y2 = 0; y2 < N; y2++) {
                        if (grid1[x1][y1] == 'Y' || grid1[x1][y1] == 'Z' || grid1[x2][y2] == 'Y' || grid1[x2][y2] == 'Z') {
                            B[x1][y1][x2][y2] = 0;
                            continue;
                        }
                        for (int i = 0; i < N; i++) {
                            for (int j = 0; j < N; j++) {
                                A[i][j] = INF;
                            }
                        }
                        Queue<int[]> Q2 = new LinkedList<>();
                        A[x1][y1] = 0;
                        Q2.offer(new int[]{x1, y1});
                        int c = 0;
                        while (!Q2.isEmpty()) {
                            int[] p2 = Q2.poll();
                            int x = p2[0], y = p2[1];
                            if (x == x2 && y == y2) {
                                c = 1;
                                break;
                            }
                            if (A[x][y] >= T || A[x][y] >= A[x][y]) continue;
                            for (int i = 0; i < 4; i++) {
                                int nx = x + dx[i], ny = y + dy[i];
                                if (nx >= 0 && nx < N && ny >= 0 && ny < N && grid1[nx][ny] != 'Y' && grid1[nx][ny] != 'Z' && A[nx][ny] == INF && A[x][y] + 1 <= A[nx][ny]) {
                                    A[nx][ny] = A[x][y] + 1;
                                    Q2.offer(new int[]{nx, ny});
                                }
                            }
                        }
                        B[x1][y1][x2][y2] = c;
                    }
                }
            }
        }
        buildNetwork();
        System.out.println(maxFlow());
    }
}
